package com.blackice.bc1;
import android.app.*;
import android.content.*;
import android.os.StatFs;
import android.widget.*;
import com.blackice.bc1.core.*;
import com.blackice.bc1.editor.*;
/** Native export form backed by the existing foreground exporter and document picker. */
final class ExportWorkspace {
 static void show(EditorActivity a){
  if(a.exportFormDialog!=null&&a.exportFormDialog.isShowing())return;
  SharedPreferences prefs=a.getSharedPreferences(ExportService.PREFS,0);
  BlackIceDialog shell=new BlackIceDialog(a,"Export video","Export",a.project.name+" · "+a.project.ratioName()+" · "+EditorActivity.clock(a.project.durationMs()));
  a.exportFormDialog=shell.dialog;
  shell.content.addView(a.label("File name",14,EditorActivity.TEXT,true));
  EditText filename=BlackIceDialog.field(a,"Export filename",a.exportDraftName==null?a.project.name.replaceAll("[^a-zA-Z0-9 ._-]","_")+".mp4":a.exportDraftName);
  add(a,shell.content,filename,8);filename.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){a.exportDraftName=s.toString();}public void afterTextChanged(android.text.Editable e){}});
  LinearLayout columns=a.column();columns.setOrientation(shell.wide?LinearLayout.HORIZONTAL:LinearLayout.VERTICAL);add(a,shell.content,columns,20);
  LinearLayout settings=a.column(),summary=a.column();summary.setPadding(a.dp(16),a.dp(16),a.dp(16),a.dp(16));summary.setBackground(com.blackice.bc1.menu.MenuPalette.surface(a,false));
  settings.addView(a.label("Video settings",18,EditorActivity.TEXT,true));summary.addView(a.label("Output summary",18,EditorActivity.TEXT,true));
  String[] labels={"Dimensions","Video codec","Audio","Estimated size","Staging space"};TextView[] values=new TextView[labels.length];
  for(int i=0;i<labels.length;i++){LinearLayout row=a.row();row.setPadding(0,a.dp(12),0,a.dp(12));row.addView(a.label(labels[i],13,EditorActivity.TEXT,true),new LinearLayout.LayoutParams(0,-2,1));values[i]=a.label("",13,EditorActivity.TEXT,false);values[i].setGravity(android.view.Gravity.END);row.addView(values[i],new LinearLayout.LayoutParams(0,-2,1));summary.addView(row);if(i<labels.length-1){android.view.View rule=new android.view.View(a);rule.setBackgroundColor(com.blackice.bc1.menu.MenuPalette.BORDER);summary.addView(rule,new LinearLayout.LayoutParams(-1,a.dp(1)));}}
  TextView error=a.note("");final Runnable[] refresh={null};EditText bitrate=BlackIceDialog.field(a,"Video bitrate in megabits per second","");bitrate.setInputType(android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL);
  final boolean[] rendering={false};java.util.List<Runnable> fields=new java.util.ArrayList<>();
  refresh[0]=()->{for(Runnable field:fields)field.run();try{ExportPlanner.Plan plan=ExportOptions.plan(a.project,prefs);values[0].setText(plan.width+" × "+plan.height);values[1].setText(plan.codec.label);values[2].setText("AAC · "+OutputSpec.AUDIO_BITRATE/1000+" kb/s");values[3].setText(String.format(java.util.Locale.US,"≈ %.1f MB",plan.estimatedBytes(a.project.durationMs())/1e6));values[4].setText(String.format(java.util.Locale.US,"%.1f GB",new StatFs(a.getCacheDir().getPath()).getAvailableBytes()/1e9));if(!bitrate.hasFocus()){rendering[0]=true;bitrate.setText(String.format(java.util.Locale.US,"%.2f",plan.bitrate/1e6));rendering[0]=false;}error.setText("Destination space is reported by its provider. Estimated size is approximate.");}catch(RuntimeException ex){for(TextView value:values)value.setText("Unavailable");error.setText("Encoder settings unavailable: "+ex.getMessage());}};
  formChoice(a,settings,"Quality",new String[]{"Low","Medium","High","Maximum","Custom"},()->prefs.getInt("export-quality",2),i->prefs.edit().putInt("export-quality",i).apply(),refresh[0],fields);
  formChoice(a,settings,"Resolution",ExportPlanner.RESOLUTION_LABELS,()->ExportPlanner.resolutionIndex(prefs.getInt(ExportPlanner.PREF_RESOLUTION,1080)),i->prefs.edit().putInt(ExportPlanner.PREF_RESOLUTION,ExportPlanner.SHORT_EDGES[i]).apply(),refresh[0],fields);
  String[] fps=new String[ExportPlanner.FRAME_RATES.length];for(int i=0;i<fps.length;i++)fps[i]=ExportPlanner.FRAME_RATES[i]+" fps";
  formChoice(a,settings,"Frame rate",fps,()->{for(int i=0;i<fps.length;i++)if(ExportPlanner.FRAME_RATES[i]==prefs.getInt("export-fps",a.project.frameRate))return i;return 0;},i->prefs.edit().putInt("export-fps",ExportPlanner.FRAME_RATES[i]).apply(),refresh[0],fields);
  formChoice(a,settings,"Codec",VideoCodec.Choice.labels(),()->VideoCodec.Choice.parse(prefs.getString(VideoCodec.Choice.PREF_KEY,null)).ordinal(),i->prefs.edit().putString(VideoCodec.Choice.PREF_KEY,VideoCodec.Choice.values()[i].name()).apply(),refresh[0],fields);
  add(a,settings,a.label("Video bitrate",14,EditorActivity.TEXT,true),12);LinearLayout rate=a.row();rate.addView(bitrate,new LinearLayout.LayoutParams(0,a.dp(48),1));TextView suffix=a.note("  Mb/s");rate.addView(suffix);add(a,settings,rate,8);add(a,settings,error,12);
  bitrate.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){if(rendering[0])return;try{double n=Double.parseDouble(s.toString());if(!Double.isFinite(n)||n<.5||n>150)throw new NumberFormatException();prefs.edit().putInt("export-quality",4).putInt("export-bitrate",(int)Math.round(n*1000000)).apply();refresh[0].run();}catch(NumberFormatException ex){bitrate.setError("Use 0.5–150 Mb/s");}}public void afterTextChanged(android.text.Editable e){}});
  columns.addView(settings,shell.wide?new LinearLayout.LayoutParams(0,-2,1.35f):new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams summaryLp=shell.wide?new LinearLayout.LayoutParams(0,-2,1):new LinearLayout.LayoutParams(-1,-2);if(shell.wide)summaryLp.leftMargin=a.dp(24);else summaryLp.topMargin=a.dp(16);columns.addView(summary,summaryLp);
  shell.footer("Back",false,shell.dialog::dismiss);TextView choose=shell.footer("Choose destination",true,()->{
   if(a.exportPickerPending||a.exporting())return;String name=filename.getText().toString().trim();if(name.isEmpty()||name.contains("/")||name.contains("\\")||name.chars().anyMatch(n->n<32)){filename.setError("Enter a valid filename");return;}
   try{double rateValue=Double.parseDouble(bitrate.getText().toString());if(!Double.isFinite(rateValue)||rateValue<.5||rateValue>150)throw new IllegalArgumentException("Use 0.5–150 Mb/s");ExportPlanner.Plan plan=ExportOptions.plan(a.project,prefs);if(!com.blackice.bc1.engine.bc.EncoderCaps.supportsBitrate(plan))throw new IllegalArgumentException("No device encoder reports support for these settings. Choose lower settings.");if(new StatFs(a.getCacheDir().getPath()).getAvailableBytes()<plan.estimatedBytes(a.project.durationMs()))throw new IllegalArgumentException("Not enough staging space. Free app storage before exporting.");
    if(!name.toLowerCase(java.util.Locale.ROOT).endsWith(".mp4"))name+=".mp4";a.exportDraftName=name;a.exportPickerPending=true;a.startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("video/mp4").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,name),EditorActivity.EXPORT);shell.dialog.dismiss();
   }catch(RuntimeException ex){a.exportPickerPending=false;a.tell(ex.getMessage());}
  });choose.setCompoundDrawablesRelativeWithIntrinsicBounds(new V1Icon("Folder",com.blackice.bc1.menu.MenuPalette.BACKGROUND),null,null,null);refresh[0].run();shell.show();
 }
 private static void add(EditorActivity a,LinearLayout parent,android.view.View v,int gap){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=a.dp(gap);parent.addView(v,lp);}
 private static void formChoice(EditorActivity a,LinearLayout parent,String title,String[] names,java.util.function.IntSupplier read,Choice pick,Runnable refresh,java.util.List<Runnable> fields){LinearLayout row=a.row();row.addView(a.label(title,13,EditorActivity.TEXT,true),new LinearLayout.LayoutParams(a.dp(100),-2));TextView button=BlackIceDialog.action(a,names[Math.max(0,Math.min(names.length-1,read.getAsInt()))]+"  ▾",false,()->{});fields.add(()->button.setText(names[Math.max(0,Math.min(names.length-1,read.getAsInt()))]+"  ▾"));button.setContentDescription(title);button.setGravity(android.view.Gravity.START|android.view.Gravity.CENTER_VERTICAL);button.setOnClickListener(v->BlackIceDialog.choices(a,title,names,read.getAsInt(),i->{pick.pick(i);button.setText(names[i]+"  ▾");refresh.run();}));row.addView(button,new LinearLayout.LayoutParams(0,-2,1));add(a,parent,row,12);}
 static void progress(EditorActivity a){
  SharedPreferences prefs=a.getSharedPreferences(ExportService.PREFS,0);LinearLayout content=a.column();content.setPadding(a.dp(16),a.dp(16),a.dp(16),a.dp(16));TextView status=a.note("");ProgressBar bar=new ProgressBar(a,null,android.R.attr.progressBarStyleHorizontal);bar.setMax(100);content.addView(status);content.addView(bar);
  LinearLayout actions=a.row();TextView play=a.button("Play Video",v->openResult(a,prefs,false));TextView share=a.button("Share",v->openResult(a,prefs,true));play.setEnabled(false);share.setEnabled(false);actions.addView(play);actions.addView(share);content.addView(actions);
  AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Export progress").setView(content).setNegativeButton("Close",null).setPositiveButton("Cancel Export",null).create();android.os.Handler handler=new android.os.Handler(android.os.Looper.getMainLooper());
  Runnable poll=new Runnable(){public void run(){if(!dialog.isShowing())return;boolean running=prefs.getBoolean("running",false);int percent=prefs.getInt("percent",-1);long elapsed=Math.max(0,((running?System.currentTimeMillis():prefs.getLong("finishedAt",System.currentTimeMillis()))-prefs.getLong("startedAt",System.currentTimeMillis()))/1000);String eta=running&&percent>=5&&percent<99&&elapsed>=20?" • About "+(elapsed*(100-percent)/percent)+" s remaining":"";
   status.setText(prefs.getString("status","Preparing export…")+"\n"+(percent>=0?percent+"% • ":"")+"Elapsed: "+elapsed+" s"+eta+"\nOutput written: "+String.format(java.util.Locale.US,"%.1f MB",prefs.getLong("outputBytes",0)/1e6));bar.setIndeterminate(running&&percent<0);bar.setProgress(Math.max(0,percent));boolean success=!running&&prefs.getBoolean("success",false);play.setEnabled(success);share.setEnabled(success);dialog.getButton(AlertDialog.BUTTON_POSITIVE).setEnabled(running);if(running)handler.postDelayed(this,500);}};
  dialog.setOnShowListener(d->{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->a.startService(new Intent(a,ExportService.class).setAction(ExportService.ACTION_CANCEL)));handler.postDelayed(poll,500);});dialog.setOnDismissListener(d->handler.removeCallbacksAndMessages(null));dialog.show();
 }
 private static void openResult(EditorActivity a,SharedPreferences prefs,boolean share){String uri=prefs.getString("uri","");if(uri.isEmpty())return;android.net.Uri file=android.net.Uri.parse(uri);Intent intent=share?new Intent(Intent.ACTION_SEND).setType("video/mp4").putExtra(Intent.EXTRA_STREAM,file):new Intent(Intent.ACTION_VIEW).setDataAndType(file,"video/mp4");intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);try{a.startActivity(share?Intent.createChooser(intent,"Share exported video"):intent);}catch(ActivityNotFoundException e){a.tell("No application can open this video.");}}
 interface Choice{void pick(int i);}
 static void choice(EditorActivity a,LinearLayout parent,String title,String[] names,int index,Choice action){TextView button=a.button(title+": "+names[Math.max(0,Math.min(index,names.length-1))],v->{});button.setOnClickListener(v->new AlertDialog.Builder(a).setTitle(title).setItems(names,(d,i)->{action.pick(i);button.setText(title+": "+names[i]);}).show());parent.addView(button);}
}
